const item = $input.first().json;
const token = item.headers?.['x-internal-token'];
const expectedToken = $vars.N8N_INTERNAL_TOKEN;
if (!token || token !== expectedToken) {
  throw new Error('Unauthorized: invalid or missing X-Internal-Token');
}

const body = item.body;
const type = body.type;
const data = body.data || {};
const to = body.to;

if (!to) throw new Error('Missing recipient email address');
if (!type) throw new Error('Missing email type');

const blueHeader = `<div style="background:#1e40af;padding:20px;border-radius:8px 8px 0 0;"><h1 style="color:white;margin:0;font-size:20px;">University Voting System</h1></div>`;
const redHeader = `<div style="background:#dc2626;padding:20px;border-radius:8px 8px 0 0;"><h1 style="color:white;margin:0;font-size:20px;">Security Alert</h1></div>`;
const footer = `<hr style="border:none;border-top:1px solid #e5e7eb;margin:20px 0;"><p style="color:#9ca3af;font-size:12px;">University Electronic Voting System &bull; Secure &bull; Anonymous &bull; Auditable</p>`;
const wrap = (header, borderColor, content) => `<!DOCTYPE html><html><body style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;padding:20px;">${header}<div style="background:white;border:1px solid ${borderColor};border-top:none;padding:30px;border-radius:0 0 8px 8px;">${content}${footer}</div></body></html>`;

let subject = '';
let html = '';

if (type === 'otp') {
  subject = 'Your Verification Code — University Voting';
  html = wrap(blueHeader, '#e5e7eb', `
    <h2 style="color:#1e40af;">Your Verification Code</h2>
    <p>Hello ${data.userName},</p>
    <p>Use the code below to sign in. It expires in <strong>${data.expiresIn}</strong>.</p>
    <div style="font-size:40px;font-weight:bold;letter-spacing:12px;text-align:center;padding:24px;background:#eff6ff;border:2px solid #bfdbfe;border-radius:8px;color:#1e40af;margin:20px 0;">${data.otp}</div>
    <p style="color:#6b7280;font-size:13px;">If you did not request this code, please ignore this email.</p>
  `);

} else if (type === 'vote-confirmation') {
  subject = 'Vote Confirmed — University Elections';
  html = wrap(blueHeader, '#e5e7eb', `
    <h2 style="color:#059669;">Your Vote Has Been Recorded</h2>
    <p>Dear ${data.userName},</p>
    <p>Your vote in <strong>${data.electionTitle}</strong> has been securely recorded.</p>
    <div style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;padding:16px;margin:20px 0;">
      <p style="margin:0 0 8px 0;color:#6b7280;font-size:13px;">RECEIPT TOKEN</p>
      <p style="margin:0;font-family:monospace;font-size:14px;word-break:break-all;color:#1f2937;">${data.receiptToken}</p>
    </div>
    <p style="color:#6b7280;font-size:13px;">Your choice remains completely anonymous.</p>
  `);

} else if (type === 'election-opened') {
  subject = `New Election Open for Voting — ${data.electionTitle}`;
  html = wrap(blueHeader, '#e5e7eb', `
    <h2 style="color:#1e40af;">Voting Is Now Open</h2>
    <p>Dear ${data.userName},</p>
    <p>A new election is now open:</p>
    <div style="background:#eff6ff;border-left:4px solid #1e40af;padding:16px;margin:20px 0;">
      <h3 style="margin:0 0 8px 0;color:#1e40af;">${data.electionTitle}</h3>
      <p style="margin:4px 0;font-size:13px;color:#6b7280;"><strong>Opens:</strong> ${data.startTime}</p>
      <p style="margin:4px 0;font-size:13px;color:#6b7280;"><strong>Closes:</strong> ${data.endTime}</p>
    </div>
    <div style="text-align:center;margin:24px 0;">
      <a href="http://localhost/elections" style="display:inline-block;background:#1e40af;color:white;padding:12px 32px;border-radius:8px;text-decoration:none;font-weight:bold;">Vote Now</a>
    </div>
  `);

} else if (type === 'election-closed') {
  const results = data.results || [];
  const totalVotes = data.totalVotes || 0;
  const rows = results.map((r, i) =>
    `<tr style="background:${i % 2 === 0 ? '#f9fafb' : 'white'}">
      <td style="padding:10px 14px;">${i + 1}</td>
      <td style="padding:10px 14px;font-weight:${i === 0 ? 'bold' : 'normal'}">${r.name}</td>
      <td style="padding:10px 14px;">${r.position || '—'}</td>
      <td style="padding:10px 14px;text-align:center;">${r.vote_count || 0}</td>
      <td style="padding:10px 14px;text-align:center;">${totalVotes > 0 ? Math.round((r.vote_count / totalVotes) * 100) : 0}%</td>
    </tr>`
  ).join('');
  const table = `<table style="width:100%;border-collapse:collapse;"><thead><tr style="background:#1e40af;color:white;"><th style="padding:10px 14px;text-align:left;">#</th><th style="padding:10px 14px;text-align:left;">Candidate</th><th style="padding:10px 14px;text-align:left;">Position</th><th style="padding:10px 14px;text-align:center;">Votes</th><th style="padding:10px 14px;text-align:center;">%</th></tr></thead><tbody>${rows}</tbody></table>`;
  subject = `Election Closed — Final Results: ${data.electionTitle}`;
  html = wrap(blueHeader, '#e5e7eb', `
    <h2 style="color:#1f2937;">Election Closed — Final Results</h2>
    <p>Dear ${data.userName},</p>
    <p>The election <strong>${data.electionTitle}</strong> has ended.</p>
    <div style="margin:20px 0;">${table}</div>
    <p style="text-align:center;color:#6b7280;">Total votes cast: <strong>${totalVotes}</strong></p>
  `);

} else if (type === 'suspicious-activity') {
  subject = 'Suspicious Activity Alert — University Voting';
  html = wrap(redHeader, '#fca5a5', `
    <h2 style="color:#dc2626;">Suspicious Activity Detected</h2>
    <p>Dear Admin,</p>
    <table style="width:100%;border-collapse:collapse;margin:20px 0;">
      <tr style="background:#fef2f2;"><td style="padding:10px 14px;font-weight:bold;width:140px;">Type</td><td style="padding:10px 14px;">${data.activityType}</td></tr>
      <tr><td style="padding:10px 14px;font-weight:bold;">Description</td><td style="padding:10px 14px;">${data.description}</td></tr>
      <tr style="background:#fef2f2;"><td style="padding:10px 14px;font-weight:bold;">User</td><td style="padding:10px 14px;">${data.userEmail}</td></tr>
      <tr><td style="padding:10px 14px;font-weight:bold;">IP</td><td style="padding:10px 14px;font-family:monospace;">${data.ipAddress}</td></tr>
      <tr style="background:#fef2f2;"><td style="padding:10px 14px;font-weight:bold;">Severity</td><td style="padding:10px 14px;">${data.severity}</td></tr>
      <tr><td style="padding:10px 14px;font-weight:bold;">Time</td><td style="padding:10px 14px;">${data.timestamp}</td></tr>
    </table>
  `);

} else {
  throw new Error(`Unknown email type: ${type}`);
}

return [{ json: { to, subject, html } }];
